SET DEFINE OFF
SET SERVEROUTPUT ON
WHENEVER SQLERROR EXIT SQL.SQLCODE ROLLBACK
DECLARE v_n NUMBER;BEGIN
 SELECT COUNT(*) INTO v_n FROM TRX_PRODUCTOS WHERE NOMBRE_PRODUCTO='Audifonos Sony WH-1000XM5' AND PRECIO_BASE=350.00 AND COSTO_UNITARIO_USD=230.00 AND FECHA_INICIO_PRECIO<=DATE '2026-01-01' AND (FECHA_FIN_PRECIO IS NULL OR FECHA_FIN_PRECIO>=DATE '2026-08-31');
