DECLARE
 v_n NUMBER;
 PROCEDURE tasa(p_fecha DATE,p_moneda VARCHAR2,p_tasa NUMBER) IS v_t NUMBER;v_act CHAR(1);BEGIN
 BEGIN SELECT TASA_USD,ACTIVO INTO v_t,v_act FROM TRX_MONEDAS WHERE FECHA=p_fecha AND MONEDA_ORIGEN=p_moneda;
 IF v_t<>p_tasa OR v_act<>'S' THEN RAISE_APPLICATION_ERROR(-20100,'Tasa existente diferente: '||p_moneda||' '||TO_CHAR(p_fecha,'YYYY-MM-DD')); END IF;
 EXCEPTION WHEN NO_DATA_FOUND THEN INSERT INTO TRX_MONEDAS(FECHA,MONEDA_ORIGEN,TASA_USD,FUENTE_TIPO_CAMBIO) VALUES(p_fecha,p_moneda,p_tasa,'SIMULADA - proyecto SQL');END;
 END;
