DECLARE
 v_id NUMBER;v_cn NUMBER;v_cli NUMBER;v_emp NUMBER;v_mp NUMBER;v_estado NUMBER;
 PROCEDURE venta(p_id NUMBER,p_fecha TIMESTAMP,p_canal VARCHAR2,p_cliente VARCHAR2,p_empleado VARCHAR2,p_moneda VARCHAR2,p_total NUMBER) IS v_n NUMBER;BEGIN
 v_id:=p_id;
 SELECT ID_CANAL INTO v_cn FROM TRX_CANALES WHERE CODIGO_CANAL=p_canal;
 SELECT ID_CLIENTE INTO v_cli FROM TRX_CLIENTES WHERE NOMBRE=p_cliente AND FECHA_REGISTRO<=CAST(p_fecha AS DATE);
 SELECT ID_EMPLEADO INTO v_emp FROM TRX_EMPLEADOS WHERE NOMBRE=p_empleado AND FECHA_CONTRATACION<=CAST(p_fecha AS DATE);
 SELECT ID_METODO_PAGO INTO v_mp FROM TRX_METODOS_PAGO WHERE NOMBRE_METODO='Tarjeta de Credito';
 SELECT ID_ESTADO_VENTA INTO v_estado FROM TRX_ESTADOS_VENTA WHERE NOMBRE_ESTADO='Pagada';
 SELECT COUNT(*) INTO v_n FROM TRX_VENTAS WHERE ID_TRANSACCION=p_id;
 IF v_n=0 THEN
 INSERT INTO TRX_VENTAS(ID_TRANSACCION,FECHA_TRANSACCION,ID_CANAL,ID_CLIENTE,ID_EMPLEADO,ID_METODO_PAGO,ID_ESTADO_VENTA,MONEDA_ORIGEN,TOTAL)
 VALUES(p_id,p_fecha,v_cn,v_cli,v_emp,v_mp,v_estado,p_moneda,p_total);
 ELSE SELECT COUNT(*) INTO v_n FROM TRX_VENTAS WHERE ID_TRANSACCION=p_id AND FECHA_TRANSACCION=p_fecha AND ID_CANAL=v_cn AND ID_CLIENTE=v_cli AND ID_EMPLEADO=v_emp AND MONEDA_ORIGEN=p_moneda AND TOTAL=p_total AND ID_METODO_PAGO=v_mp AND ID_ESTADO_VENTA=v_estado AND ACTIVO='S';
 IF v_n<>1 THEN RAISE_APPLICATION_ERROR(-20102,'ID reservado ocupado: '||p_id); END IF; END IF;
 END;
 PROCEDURE linea(p_producto VARCHAR2,p_cant NUMBER,p_precio NUMBER,p_desc NUMBER,p_imp NUMBER,p_promo VARCHAR2) IS v_p NUMBER;v_pr NUMBER;v_n NUMBER;BEGIN
 SELECT ID_PRODUCTO INTO v_p FROM TRX_PRODUCTOS WHERE NOMBRE_PRODUCTO=p_producto;
 IF p_promo IS NOT NULL THEN SELECT ID_PROMOCION INTO v_pr FROM TRX_PROMOCIONES WHERE DESCRIPCION=p_promo; END IF;
 SELECT COUNT(*) INTO v_n FROM TRX_DETALLE WHERE ID_TRANSACCION=v_id AND ID_PRODUCTO=v_p;
 IF v_n=0 THEN INSERT INTO TRX_DETALLE(ID_TRANSACCION,ID_PRODUCTO,ID_PROMOCION,CANTIDAD,PRECIO_UNITARIO,DESCUENTO,IMPUESTO) VALUES(v_id,v_p,v_pr,p_cant,p_precio,p_desc,p_imp);
 ELSE SELECT COUNT(*) INTO v_n FROM TRX_DETALLE WHERE ID_TRANSACCION=v_id AND ID_PRODUCTO=v_p AND NVL(ID_PROMOCION,-1)=NVL(v_pr,-1) AND CANTIDAD=p_cant AND PRECIO_UNITARIO=p_precio AND DESCUENTO=p_desc AND IMPUESTO=p_imp AND ACTIVO='S';
 IF v_n<>1 THEN RAISE_APPLICATION_ERROR(-20103,'Detalle existente diferente: '||v_id); END IF;END IF;
 END;
 PROCEDURE fin_venta(p_lineas NUMBER) IS v_n NUMBER;v_total NUMBER;v_decl NUMBER;BEGIN
 SELECT COUNT(*),SUM(CANTIDAD*PRECIO_UNITARIO-DESCUENTO+IMPUESTO) INTO v_n,v_total FROM TRX_DETALLE WHERE ID_TRANSACCION=v_id AND ACTIVO='S';
 SELECT TOTAL INTO v_decl FROM TRX_VENTAS WHERE ID_TRANSACCION=v_id;
 IF v_n<>p_lineas OR ABS(v_total-v_decl)>0.01 THEN RAISE_APPLICATION_ERROR(-20104,'Venta no concilia: '||v_id); END IF;
 END;
BEGIN
