COMMIT;
-- Mantener la secuencia por encima de los IDs explicitos reservados.
ALTER TABLE TRX_VENTAS MODIFY ID_TRANSACCION GENERATED BY DEFAULT AS IDENTITY (START WITH LIMIT VALUE);
PROMPT Datos simulados enero-agosto cargados. Ejecutar PKG_ETL_VENTAS.PR_EJECUTAR_ETL.
